// Samples of drivers/java/README.md, compiled by `check` (AC-DRV-002), and the JPMS smoke test
// TC-DRV-JAVA-026: this project is the named module io.rustegon.samples; `jpmsSmoke` and
// `jpmsSmokeJdk25` run it on the module path (driver, gRPC, protobuf, slf4j as modules) with
// a codec generated by rustegon-processor. Not published.
plugins {
    application
}

java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

dependencies {
    implementation(project(":driver"))
    annotationProcessor(project(":processor"))
}

tasks.withType<JavaCompile>().configureEach {
    options.encoding = "UTF-8"
    options.release = 21
    options.compilerArgs.addAll(listOf("-Xlint:all,-processing", "-Werror"))
}

application {
    mainModule = "io.rustegon.samples"
    mainClass = "io.rustegon.samples.JpmsSmoke"
}

val jpmsSmoke = tasks.register<JavaExec>("jpmsSmoke") {
    description = "TC-DRV-JAVA-026: runs the samples module on the module path (JDK 21)."
    group = LifecycleBasePlugin.VERIFICATION_GROUP
    classpath = sourceSets.main.get().runtimeClasspath
    mainModule = "io.rustegon.samples"
    mainClass = "io.rustegon.samples.JpmsSmoke"
}
val jpmsSmokeJdk25 = tasks.register<JavaExec>("jpmsSmokeJdk25") {
    description = "TC-DRV-JAVA-026: runs the samples module on the module path (JDK 25)."
    group = LifecycleBasePlugin.VERIFICATION_GROUP
    classpath = sourceSets.main.get().runtimeClasspath
    mainModule = "io.rustegon.samples"
    mainClass = "io.rustegon.samples.JpmsSmoke"
    javaLauncher = javaToolchains.launcherFor { languageVersion = JavaLanguageVersion.of(25) }
    // JDK 24+ warns when Netty loads its native transport without this (README "JPMS").
    jvmArgs("--enable-native-access=io.grpc.netty.shaded")
}

tasks.named("check") {
    dependsOn(jpmsSmoke, jpmsSmokeJdk25)
}
